<script setup lang="ts">
import Draggable from 'vuedraggable'
import { openStreetMapEmbedUrl, parseMapCoordinates } from '~~/shared/map-location'
import { prepareImageUpload } from '~~/shared/image-upload'
const props = defineProps<{ ev: any }>(); const emit = defineEmits<{ refresh: [] }>(); const toast = useToast(); const { current } = useOrg()
const loc = (d: string | null) => (d ? new Date(new Date(d).getTime() - new Date(d).getTimezoneOffset() * 60000).toISOString().slice(0, 16) : '')
const initialFaq: { question: string; answer: string }[] = Array.isArray(props.ev.faq) ? props.ev.faq : []
const f = reactive({ title: props.ev.title, description: props.ev.description, category: props.ev.category, visibility: props.ev.visibility, startsAt: loc(props.ev.startsAt), endsAt: loc(props.ev.endsAt), salesOpenAt: loc(props.ev.salesOpenAt), salesCloseAt: loc(props.ev.salesCloseAt), capacity: props.ev.capacity, maxPerOrder: props.ev.maxPerOrder, themeId: props.ev.themeId, accessTerms: props.ev.accessTerms, templateId: props.ev.templateId ?? '', offlineEnabled: props.ev.offlineEnabled, transfersEnabled: props.ev.transfersEnabled, refundAllowed: props.ev.refundPolicy.allowed, refundHours: props.ev.refundPolicy.untilHoursBefore, accessCode: '', venueName: props.ev.location?.venueName ?? '', address: props.ev.location?.address ?? '', city: props.ev.location?.city ?? '', lat: props.ev.location?.lat ?? null, lng: props.ev.location?.lng ?? null, faq: initialFaq.map((item) => ({ question: item.question, answer: item.answer, key: crypto.randomUUID() })), countdownEnabled: props.ev.countdownEnabled ?? true, countdownUnits: [...(props.ev.countdownUnits ?? ['days', 'hours', 'minutes', 'seconds'])] as string[] })
const { data: templates } = await useAsyncData(`tpls-${props.ev.id}`, () => api<any[]>('/api/templates', { query: { orgId: props.ev.organizationId } }), { server: false })
const ask = (m: string) => window.confirm(m)
const busy = ref(false); const iso = (s: string) => (s ? new Date(s).toISOString() : null)
const mapLocationInput = ref('')
const mapLocationError = ref('')
const mapPosition = computed(() => {
  if (f.lat === null || f.lat === '' || f.lng === null || f.lng === '') return null
  const lat = Number(f.lat); const lng = Number(f.lng)
  return Number.isFinite(lat) && Number.isFinite(lng) && lat >= -90 && lat <= 90 && lng >= -180 && lng <= 180 ? { lat, lng } : null
})
function applyMapLocation() {
  const position = parseMapCoordinates(mapLocationInput.value)
  if (!position) {
    mapLocationError.value = 'Coordonnées introuvables dans ce lien. Colle un lien Google Maps complet avec position ou saisis latitude, longitude.'
    return
  }
  f.lat = position.lat
  f.lng = position.lng
  mapLocationError.value = ''
}
function addFaq() { if (f.faq.length < 20) f.faq.push({ key: crypto.randomUUID(), question: '', answer: '' }) }
function moveFaq(index: number, offset: number) {
  const next = index + offset
  if (next < 0 || next >= f.faq.length) return
  const [item] = f.faq.splice(index, 1)
  if (item) f.faq.splice(next, 0, item)
}
function mapsSearch() { return `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent([f.venueName, f.address, f.city].filter(Boolean).join(', '))}` }
async function save() { busy.value = true; try { await api(`/api/manage/events/${props.ev.id}`, { method: 'PATCH', body: { title: f.title, description: f.description, category: f.category, visibility: f.visibility, startsAt: iso(f.startsAt), endsAt: iso(f.endsAt), salesOpenAt: iso(f.salesOpenAt), salesCloseAt: iso(f.salesCloseAt), capacity: f.capacity, maxPerOrder: f.maxPerOrder, themeId: f.themeId, accessTerms: f.accessTerms, templateId: f.templateId || null, offlineEnabled: f.offlineEnabled, transfersEnabled: f.transfersEnabled, refundPolicy: { allowed: f.refundAllowed, untilHoursBefore: f.refundHours }, faq: f.faq.filter((item) => item.question.trim() && item.answer.trim()).map(({ question, answer }) => ({ question, answer })), countdownEnabled: f.countdownEnabled, countdownUnits: f.countdownUnits, ...(f.accessCode ? { accessCode: f.accessCode } : {}), venueName: f.venueName, address: f.address, city: f.city, lat: f.lat === null || f.lat === ('' as any) ? null : Number(f.lat), lng: f.lng === null || f.lng === ('' as any) ? null : Number(f.lng) } }); toast.ok('Événement enregistré'); emit('refresh') } catch (e) { toast.err(errMsg(e)) } finally { busy.value = false } }
async function status(action: string) { try { await api(`/api/manage/events/${props.ev.id}/status`, { method: 'POST', body: { action } }); toast.ok('Statut mis à jour'); emit('refresh') } catch (e) { toast.err(errMsg(e)) } }
async function dup() { try { const r = await api<{ id: string }>(`/api/manage/events/${props.ev.id}/duplicate`, { method: 'POST' }); await navigateTo(`/app/events/${r.id}`) } catch (e) { toast.err(errMsg(e)) } }
const poster = ref<HTMLInputElement>(); const posterUrl = ref(props.ev.posterUrl ?? '')
watch(() => props.ev.posterUrl, (url) => { posterUrl.value = url ?? '' })
async function upPoster(e: Event) { const input = e.target as HTMLInputElement; const file = input.files?.[0]; if (!file) return; try { const prepared = await prepareImageUpload(file); const fd = new FormData(); fd.append('orgId', props.ev.organizationId); fd.append('kind', 'poster'); fd.append('file', prepared, file.name); const r = await $fetch<any>('/api/uploads', { method: 'POST', body: fd }); await api(`/api/manage/events/${props.ev.id}`, { method: 'PATCH', body: { posterKey: r.key } }); posterUrl.value = r.url; toast.ok('Affiche enregistrée') } catch (er) { const error = er as { data?: { statusMessage?: string }; statusMessage?: string }; toast.err(error.data?.statusMessage || error.statusMessage || (er instanceof Error ? er.message : 'Téléversement refusé')) } finally { input.value = '' } }
const qr = ref(''); onMounted(async () => { qr.value = await qrFor(props.ev.shareUrl) })
const copy = async () => { await navigator.clipboard.writeText(props.ev.shareUrl); toast.ok('Lien copié') }
const camp = ref('instagram'); const campUrl = computed(() => `${props.ev.shareUrl}${props.ev.shareUrl.includes('?') ? '&' : '?'}ref=${encodeURIComponent(camp.value)}`)
void current
</script>
<template>
  <div class="grid gap-6 xl:grid-cols-[1fr_340px]">
    <form class="card space-y-5 p-5" @submit.prevent="save">
      <h2 class="text-lg font-bold">Informations</h2>
      <div class="grid gap-4 sm:grid-cols-2"><label class="block sm:col-span-2"><span class="label">Titre</span><input v-model="f.title" required minlength="3" class="input"></label>
        <div class="sm:col-span-2"><span class="label">Description de l’événement</span><RichTextEditor v-model="f.description" label="Description de l’événement" :max-characters="20_000" hint="La mise en forme et les liens sont nettoyés avant l’enregistrement." /></div>
        <label class="block"><span class="label">Catégorie</span><select v-model="f.category" class="input"><option v-for="c in ['soirée', 'concert', 'festival', 'conférence', 'anniversaire', 'privé']" :key="c">{{ c }}</option></select></label>
        <label class="block"><span class="label">Visibilité</span><select v-model="f.visibility" class="input"><option value="public">Public (listé)</option><option value="private">Privé (lien secret)</option><option value="invite">Sur invitation (code d’accès)</option></select></label>
        <label v-if="f.visibility !== 'public'" class="block sm:col-span-2"><span class="label">Code d’accès {{ ev.hasAccessCode ? '(défini : saisir pour le changer)' : '(facultatif pour un lien privé)' }}</span><input v-model="f.accessCode" minlength="4" class="input" autocomplete="off"></label>
        <label class="block"><span class="label">Début</span><input v-model="f.startsAt" type="datetime-local" required class="input"></label><label class="block"><span class="label">Fin</span><input v-model="f.endsAt" type="datetime-local" class="input"></label>
        <label class="block"><span class="label">Ouverture de la billetterie</span><input v-model="f.salesOpenAt" type="datetime-local" class="input"></label><label class="block"><span class="label">Fermeture de la billetterie</span><input v-model="f.salesCloseAt" type="datetime-local" class="input"></label>
        <label class="block"><span class="label">Capacité totale</span><input v-model.number="f.capacity" type="number" min="1" required class="input"></label><label class="block"><span class="label">Billets max. par commande</span><input v-model.number="f.maxPerOrder" type="number" min="1" max="50" class="input"></label></div>
      <h2 class="pt-2 text-lg font-bold">Lieu</h2>
      <div class="grid gap-4 sm:grid-cols-2"><label class="block"><span class="label">Nom du lieu</span><input v-model="f.venueName" class="input"></label><label class="block"><span class="label">Ville</span><input v-model="f.city" class="input"></label><label class="block sm:col-span-2"><span class="label">Adresse</span><input v-model="f.address" class="input"></label><div class="flex flex-col gap-2 sm:col-span-2 sm:flex-row"><input v-model="mapLocationInput" class="input min-w-0 flex-1" aria-label="Lien Google Maps ou coordonnées" placeholder="Colle un lien Google Maps ou saisis latitude, longitude"><button type="button" class="btn btn-ghost shrink-0" @click="applyMapLocation">Placer sur la carte</button></div><p v-if="mapLocationError" class="text-sm text-red-300 sm:col-span-2" role="alert">{{ mapLocationError }}</p><label class="block"><span class="label">Latitude</span><input v-model="f.lat" type="number" min="-90" max="90" step="any" class="input"></label><label class="block"><span class="label">Longitude</span><input v-model="f.lng" type="number" min="-180" max="180" step="any" class="input"></label><a v-if="f.venueName || f.address || f.city" :href="mapsSearch()" target="_blank" rel="noopener" class="text-sm text-accent underline sm:col-span-2">Rechercher ce lieu sur Google Maps ↗</a><div v-if="mapPosition" class="overflow-hidden rounded-xl border border-line sm:col-span-2"><iframe :src="openStreetMapEmbedUrl(mapPosition)" title="Aperçu de la carte du lieu" loading="lazy" referrerpolicy="no-referrer" class="h-64 w-full border-0"></iframe><p class="border-t border-line px-3 py-2 text-xs text-muted">Position : {{ mapPosition.lat }}, {{ mapPosition.lng }} · Carte OpenStreetMap</p></div><p v-else-if="(f.lat !== null && f.lat !== '') || (f.lng !== null && f.lng !== '')" class="text-sm text-amber-300 sm:col-span-2">Renseigne une latitude et une longitude valides pour afficher la carte.</p></div>
      <section class="space-y-3 border-t border-line pt-4"><div class="flex items-center justify-between gap-2"><h3 class="font-bold">Questions fréquentes</h3><button type="button" class="btn btn-ghost !min-h-[40px]" :disabled="f.faq.length >= 20" @click="addFaq">Ajouter</button></div><p v-if="f.faq.length" class="text-xs text-muted">Glisse pour réordonner l’affichage, ou utilise les flèches au clavier.</p><Draggable v-model="f.faq" item-key="key" handle=".faq-drag-handle" ghost-class="sortable-ghost" chosen-class="sortable-chosen" :animation="180" class="space-y-3"><template #item="{ element: item, index: i }"><article class="grid gap-3 rounded-xl border border-line bg-surface/30 p-3"><div class="flex items-center gap-2"><button type="button" class="faq-drag-handle grid h-10 w-10 cursor-grab touch-none place-items-center rounded-lg border border-line text-muted hover:border-accent hover:text-accent active:cursor-grabbing" :aria-label="`Réordonner la question ${i + 1}`" title="Glisser pour réordonner">⠿</button><span class="text-xs font-semibold text-muted">Question {{ i + 1 }}</span><div class="ml-auto flex gap-1"><button type="button" class="grid h-10 w-10 place-items-center rounded-lg border border-line text-muted hover:text-accent disabled:opacity-40" :disabled="i === 0" :aria-label="`Déplacer la question ${i + 1} vers le haut`" @click="moveFaq(i, -1)">↑</button><button type="button" class="grid h-10 w-10 place-items-center rounded-lg border border-line text-muted hover:text-accent disabled:opacity-40" :disabled="i === f.faq.length - 1" :aria-label="`Déplacer la question ${i + 1} vers le bas`" @click="moveFaq(i, 1)">↓</button><button type="button" class="grid h-10 w-10 place-items-center rounded-lg border border-line text-red-300 hover:bg-red-400/10" :aria-label="`Supprimer la question ${i + 1}`" @click="f.faq.splice(i, 1)">×</button></div></div><label class="block"><span class="label">Question</span><input v-model="item.question" maxlength="160" class="input"></label><label class="block"><span class="label">Réponse</span><textarea v-model="item.answer" maxlength="2000" rows="2" class="input !py-3" /></label></article></template></Draggable></section>
      <section class="space-y-3 border-t border-line pt-4"><label class="flex items-center gap-3 font-semibold"><input v-model="f.countdownEnabled" type="checkbox" class="h-5 w-5 accent-[rgb(var(--c-a))]">Afficher le compte à rebours</label><div v-if="f.countdownEnabled" class="flex flex-wrap gap-x-5 gap-y-2 text-sm"><label v-for="unit in [{ id: 'days', label: 'Jours' }, { id: 'hours', label: 'Heures' }, { id: 'minutes', label: 'Minutes' }, { id: 'seconds', label: 'Secondes' }]" :key="unit.id" class="flex items-center gap-2"><input v-model="f.countdownUnits" type="checkbox" :value="unit.id" class="accent-[rgb(var(--c-a))]">{{ unit.label }}</label></div><p v-if="f.countdownEnabled && !f.countdownUnits.length" class="text-sm text-red-300">Choisis au moins une unité.</p></section>
      <h2 class="pt-2 text-lg font-bold">Billets et règles</h2>
      <div class="grid gap-4 sm:grid-cols-2"><label class="block"><span class="label">Modèle de billet</span><select v-model="f.templateId" class="input"><option value="">Modèle par défaut</option><option v-for="t in templates" :key="t.id" :value="t.id">{{ t.name }}{{ t.published ? '' : ' (brouillon)' }}</option></select><NuxtLink to="/app/studio" class="hint underline">Ouvrir le Studio</NuxtLink></label>
        <label class="block"><span class="label">Conditions d’accès (imprimées sur le billet)</span><input v-model="f.accessTerms" maxlength="1000" class="input"></label>
        <label class="flex min-h-[44px] items-center gap-3"><input v-model="f.transfersEnabled" type="checkbox" class="h-5 w-5 accent-[rgb(var(--c-a))]"> Billets transférables</label>
        <label class="flex min-h-[44px] items-center gap-3"><input v-model="f.offlineEnabled" type="checkbox" class="h-5 w-5 accent-[rgb(var(--c-a))]"> Autoriser le mode scanner hors ligne</label>
        <label class="flex min-h-[44px] items-center gap-3"><input v-model="f.refundAllowed" type="checkbox" class="h-5 w-5 accent-[rgb(var(--c-a))]"> Remboursements possibles</label><label v-if="f.refundAllowed" class="block"><span class="label">Jusqu’à (heures avant)</span><input v-model.number="f.refundHours" type="number" min="0" class="input"></label></div>
      <p v-if="f.offlineEnabled" class="rounded-xl border border-amber-400/40 bg-amber-400/10 p-3 text-sm text-amber-200">Hors ligne : plusieurs appareils déconnectés ne se voient pas entre eux. Un billet peut être accepté deux fois avant synchronisation ; les doublons sont signalés à la reconnexion.</p>
      <h2 class="pt-2 text-lg font-bold">Thème de la page de vente</h2><ThemeGallery v-model="f.themeId" scope="local" />
      <div class="flex justify-end"><button class="btn btn-primary" :disabled="busy || (f.countdownEnabled && !f.countdownUnits.length)">{{ busy ? 'Enregistrement…' : 'Enregistrer' }}</button></div>
    </form>
    <div class="space-y-5">
      <div class="card space-y-3 p-5"><h2 class="text-lg font-bold">Publication</h2><p class="text-sm"><span class="chip capitalize">{{ ev.status }}</span></p>
        <div class="grid gap-2"><button v-if="ev.status !== 'published'" class="btn btn-primary" @click="status('publish')">Publier / ouvrir les ventes</button><button v-if="ev.status === 'published'" class="btn btn-ghost" @click="status('suspend')">Suspendre les ventes</button><button v-if="ev.status === 'published'" class="btn btn-ghost" @click="status('close')">Clôturer les ventes</button><button class="btn btn-ghost" @click="dup">Dupliquer l’événement</button><button v-if="ev.status !== 'cancelled'" class="btn btn-danger" @click="ask('Annuler définitivement cet événement ?') && status('cancel')">Annuler l’événement</button></div></div>
      <div class="card space-y-3 p-5"><h2 class="text-lg font-bold">Affiche</h2><img v-if="posterUrl" :src="posterUrl" alt="Affiche de l’événement" class="w-full rounded-xl" @error="posterUrl = ''"><p v-else-if="ev.posterKey" class="text-sm text-amber-300">Affiche enregistrée, mais son aperçu ne peut pas être chargé. Vérifie la configuration du stockage ou téléverse-la à nouveau.</p><button class="btn btn-ghost w-full" :disabled="busy" @click="poster?.click()">Téléverser ou remplacer (PNG/JPG, jusqu’à 25 Mo avant compression)</button><input ref="poster" type="file" accept="image/png,image/jpeg" class="hidden" @change="upPoster"></div>
      <div class="card space-y-3 p-5"><h2 class="text-lg font-bold">Partage et promotion</h2><div v-if="qr" class="mx-auto w-40 rounded-xl bg-white p-2"><img :src="qr" alt="QR code de la page publique" class="w-full"></div><input :value="ev.shareUrl" readonly class="input text-xs" aria-label="Lien de partage"><div class="flex gap-2"><button class="btn btn-ghost flex-1" @click="copy">Copier</button><a v-if="qr" :href="qr" download="qr-evenement.png" class="btn btn-ghost flex-1">QR (PNG)</a></div>
        <label class="block"><span class="label">Lien de campagne</span><select v-model="camp" class="input"><option>instagram</option><option>facebook</option><option>whatsapp</option><option>tiktok</option><option>affilie</option></select></label><input :value="campUrl" readonly class="input text-xs" aria-label="Lien de campagne"><p class="hint">Les ventes sont rattachées à la campagne et visibles dans l’onglet Commandes.</p></div>
    </div>
  </div>
</template>
